import React, { useState, useEffect } from 'react';
import ChatPage from './pages/ChatPage';
import SystemInfoPage from './pages/SystemInfoPage';
import './styles/base.css';
import './styles/components.css';
import './styles/utilities.css';

function App() {
  // 기본 사용자 상태를 설정하여 항상 로그인된 상태로 유지
  const [user] = useState({
    userId: '1',
    username: 'testUser'
  });
  const [userCount] = useState(10); // 고정된 사용자 수
  const [showInfo, setShowInfo] = useState(false);

  const handleInfoButtonClick = () => {
    setShowInfo(true);
  };

  const handleHomeButtonClick = () => {
    setShowInfo(false);
  };

  const HomeButton = () => (
    <button 
      onClick={handleHomeButtonClick}
      style={{
        position: 'absolute',
        left: '20px',
        top: '20px',
        padding: '8px 16px',
        backgroundColor: '#4a90e2',
        color: 'white',
        border: 'none',
        borderRadius: '4px',
        cursor: 'pointer',
        zIndex: 1000
      }}
    >
      홈으로
    </button>
  );

  const MainButtons = () => (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      gap: '20px',
      justifyContent: 'center',
      alignItems: 'center',
      height: '100%'
    }}>
      <p style={{
        fontSize: '1.5rem',
        color: '#4a5568',
        textAlign: 'center',
        marginBottom: '30px',
        lineHeight: '1.6'
      }}>
        "다소니"는<br />
        사랑하는 사람을 뜻하는 순우리말입니다
      </p>
      <button 
        onClick={handleInfoButtonClick}
        style={{
          padding: '15px 30px',
          fontSize: '18px',
          backgroundColor: '#28a745',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          cursor: 'pointer'
        }}
      >
        시스템 소개
      </button>
    </div>
  );

  return (
    <div className="App">
      <div className="main-section">
        <header className="main-header">
          <h1>다 소 니</h1>
        </header>
        <main className="main-content">
          {showInfo ? (
            <>
              <HomeButton />
              <SystemInfoPage />
            </>
          ) : (
            <MainButtons />
          )}
        </main>
      </div>
      <div className="side-container">
        <header className="side-header">
          <span className="user-count">현재 접속자 수: {userCount}</span>
          <div>
            <span className="user-nickname">{user.username}님</span>
          </div>
        </header>
        <ChatPage 
          user={user}
          chatBanTimeLeft={0}
          sendMessage={(msg) => console.log('Message sent:', msg)}
        />
      </div>
    </div>
  );
}

export default App;
